def ship_within_days(weights, days):
    def days_needed(capacity):
        needed = 1
        current = 0
        for w in weights:
            if current + w > capacity:
                needed += 1
                current = 0
            current += w
        return needed

    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo
